from .money import parse_amount_cents, cents_to_amount, format_amount

_MAX_TOTAL_CENTS = 100_000_000  # 1000000.00


def make_invoice(amounts):
    items = list(amounts)
    total_cents = 0
    for item in items:
        total_cents += parse_amount_cents(item)
    if total_cents > _MAX_TOTAL_CENTS:
        raise ValueError("total exceeds 1000000.00")
    return {"total": format_amount(cents_to_amount(total_cents)), "count": len(items)}

